202→            } else {
203→                // refresh interval: -1로 변경. 색인도중 검색노출하지 않음. 성능 향상 목적.
204→                // 셋팅무시 설정이 있을시 indexing 맵에서 role 제거
205→                logger.info("ES 인덱스 존재 시, indexing settings >>> {}", indexing);
206→                boolean isAcknowledged = elasticsearchFactoryWrapper.updateIndexSettings(clusterId, index.getIndex(), indexing);
207→                logger.debug("edit settings : {} ", isAcknowledged);
208→            }
209→        }catch (IOException e){
210→            logger.error("{}", e);
211→        }
212→    }
