214→    private Map<String, Object> makeRequestBodyToIndexer(UUID clusterId, Collection collection, Collection.Index index) throws IndexingJobFailureException, ConvertYamlException {
215→        Collection.Launcher launcher = collection.getLauncher();
216→        if (launcher.getScheme() == null || "".equals(launcher.getScheme())) {
217→            launcher.setScheme("http");
218→        }
219→
220→        Map<String, Object> body = YamlUtils.convertYamlToMap(launcher.getYaml());
221→
222→        String jdbcId = collection.getJdbcId();
223→        Map<String, Object> jdbcContent = getJdbcContent(clusterId, jdbcId);
224→        body.put("_jdbc", jdbcContent);
225→        body.put("index", index.getIndex());
226→        body.put("_indexingSettings", indexing);
227→
228→        // null 대비 에러처리
229→        if (collection.getEsHost() != null && !collection.getEsHost().equals("")) {
230→            body.put("host", collection.getEsHost());
231→        }
232→
233→        int esPort = 9200;
234→        if (collection.getEsPort() != null && !collection.getEsPort().equals("")) {
235→            try {
236→                esPort = Integer.parseInt(collection.getEsPort());
237→            } catch (NumberFormatException e) {
238→                logger.info("", e);
239→            }
240→            body.put("port", esPort);
