277→    private IndexingInfo makeIndexingStatus(UUID clusterId,
278→                                            Collection collection,
279→                                            Collection.Index targetIndex,
280→                                            String indexingJobId,
281→                                            IndexingStep currentStep,
282→                                            Queue<IndexingStep> actionSteps){
283→        IndexingInfo indexingInfo = new IndexingInfo();
