354→    public void expose(UUID clusterId, Collection collection, String targetIndex) throws IOException {
355→        if(!isCreatedIndexes(clusterId, collection)){
356→            logger.info("{} 컬렉션의 인덱스가 생성되지 않아 Expose 중지", collection.getBaseId());
357→            return;
