380→    private void changeAliasWithTargetIndex(UUID clusterId, Collection collection, String targetIndex) throws IOException{
381→        IndicesAliasesRequest request = new IndicesAliasesRequest();
382→
383→        String baseId = collection.getBaseId();
384→        Collection.Index indexA = collection.getIndexA();
385→        Collection.Index indexB = collection.getIndexB();
386→
387→        String nameOfindexA = indexA.getIndex() != null ? indexA.getIndex() : "" ;
388→        String nameOfindexB = indexB.getIndex() != null ? indexB.getIndex() : "" ;
389→
390→        String toAddIndex = getIndexToAddAlias(nameOfindexA, nameOfindexB, targetIndex);
391→        String toRemoveIndex = getIndexToRemoveAlias(nameOfindexA, nameOfindexB, targetIndex);
392→
393→        try {
394→            request.addAliasAction(new IndicesAliasesRequest.
395→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
396→                    .index(toAddIndex).alias(baseId));
397→            request.addAliasAction(new IndicesAliasesRequest.
398→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.REMOVE)
399→                    .index(toRemoveIndex).alias(baseId));
400→            elasticsearchFactoryWrapper.updateAliases(clusterId, request);
401→        } catch (Exception e) {
402→            request = new IndicesAliasesRequest();
403→            request.addAliasAction(new IndicesAliasesRequest.
404→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
405→                    .index(toAddIndex).alias(baseId));
406→            // 교체
407→            elasticsearchFactoryWrapper.updateAliases(clusterId, request);
408→        }
409→    }
