411→    private String getIndexToAddAlias(String indexA, String indexB, String targetIndex){
412→        if (indexA.equals(targetIndex)) {
413→            return indexA;
414→        } else {
415→            return indexB;
416→        }
417→    }
418→
419→    private String getIndexToRemoveAlias(String indexA, String indexB, String targetIndex){
420→        if (indexA.equals(targetIndex)) {
421→            return indexB;
422→        } else {
423→            return indexA;
424→        }
425→    }
