427→    private String changeAliasWithoutTargetIndex(UUID clusterId, Collection collection) throws IOException {
428→        IndicesAliasesRequest request = new IndicesAliasesRequest();
429→
430→        String baseId = collection.getBaseId();
431→        Collection.Index indexA = collection.getIndexA();
432→        Collection.Index indexB = collection.getIndexB();
433→
434→        String targetIndex;
435→
436→        if (isExistsIfOnlyIndexB(collection)) {
437→            // 1. -b 인덱스만 있을 경우
438→            request.addAliasAction(new IndicesAliasesRequest.
439→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
440→                    .index(indexB.getIndex()).alias(baseId));
441→            targetIndex = indexB.getIndex();
442→        } else if (isExistsIfOnlyIndexA(collection)) {
443→            // 2. -a 인덱스만 있을 경우
444→            request.addAliasAction(new IndicesAliasesRequest.
445→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
446→                    .index(indexA.getIndex()).alias(baseId));
447→            targetIndex = indexA.getIndex();
448→        } else {
449→            // 3. -a, -b 인덱스가 있을 경우
450→            // 인덱스 히스토리 로그를 찾아 최근에 성공한 인덱스를 찾는다
451→            targetIndex = findRecentlyIndexingSuccessIndex(clusterId, indexA.getIndex(), indexB.getIndex());
452→
453→            if ("".equals(targetIndex)) {
454→                // 3.1) -a, -b 인덱스 둘다 있지만 alias가 셋팅이 되지 않은 경우
455→                request.addAliasAction(new IndicesAliasesRequest.
456→                        AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
457→                        .index(indexA.getIndex()).alias(baseId));
458→
459→                targetIndex = indexA.getIndex();
460→            } else {
461→                // 3.2) -a, -b 인덱스 둘다 있지만 alias가 셋팅이 되어 있는 경우
462→                String addIndex = getIndexToAddAlias(indexA.getIndex(), indexB.getIndex(), targetIndex);
463→                String removeIndex = getIndexToRemoveAlias(indexA.getIndex(), indexB.getIndex(), targetIndex);
464→
465→                request.addAliasAction(new IndicesAliasesRequest.
466→                        AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
467→                        .index(addIndex).alias(baseId));
468→                request.addAliasAction(new IndicesAliasesRequest.
469→                        AliasActions(IndicesAliasesRequest.AliasActions.Type.REMOVE)
470→                        .index(removeIndex).alias(baseId));
471→            }
472→        }
473→
474→        // Alias 교체
475→        elasticsearchFactoryWrapper.updateAliases(clusterId, request);
476→        return targetIndex;
477→    }
