    String reindexFinishAndWaitMs = (String) payload.get("reindexFinishAndWaitMs");
    String pipeLine = (String) payload.getOrDefault("pipeLine", "");

    try (RestHighLevelClient client = new RestHighLevelClient(restClientBuilder)) {
