            try {
                while (!isTaskDone(client, taskId)) {
                    if (job != null && job.getStopSignal() != null && job.getStopSignal()) {
                        logger.info("Stop Signal");
                        throw new StopSignalException();
                    }

                    Thread.sleep(Long.parseLong(reindexCheckMs));

